"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["60240"],{91455(e,a,t){t.r(a),t.d(a,{metadata:()=>s,default:()=>l,frontMatter:()=>c,contentTitle:()=>d,toc:()=>u,assets:()=>h});var s=JSON.parse('{"id":"nhcx/v1/api/adjudicator/endpoints/adjudicator-adjudicator-role","title":"Submit the adjudicator: role for a case","description":"Asks the NHCX Payer Service which role in the State Health Agency\'s Transaction Management System holds a PMJAY case, and so which actions may be taken on...","source":"@site/docs/nhcx/v1/api/adjudicator/endpoints/adjudicator-adjudicator-role.mdx","sourceDirName":"nhcx/v1/api/adjudicator/endpoints","slug":"/nhcx/v1/api/adjudicator/endpoints/adjudicator-adjudicator-role","permalink":"/docs/main/docs/nhcx/v1/api/adjudicator/endpoints/adjudicator-adjudicator-role","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Submit the adjudicator: role for a case","sidebar_label":"Submit the adjudicator: role for a case","sidebar_class_name":"api-method api-method--post","description":"Asks the NHCX Payer Service which role in the State Health Agency\'s Transaction Management System holds a PMJAY case, and so which actions may be taken on...","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-adjudicator.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Overview","permalink":"/docs/main/docs/nhcx/v1/api/adjudicator/"},"next":{"title":"Submit the adjudicator: act on a case","permalink":"/docs/main/docs/nhcx/v1/api/adjudicator/endpoints/adjudicator-adjudicator-process"}}'),n=t(62540),r=t(43023),o=t(75064),i=JSON.parse('{"id":"adjudicator_adjudicator_role","module":"PMJAY adjudicator","moduleId":"adjudicator","kind":"operation","method":"POST","path":"/pmjay/sbxhcx/nhcxpayerservice/v1/get/user-role","server":"https://apisbx.abdm.gov.in","servers":[{"url":"https://apisbx.abdm.gov.in","description":"Sandbox, PMJAY payer service, role lookup."}],"summary":"Adjudicator: role for a case","title":"Submit the adjudicator: role for a case","description":"Asks the NHCX Payer Service which role in the State Health Agency\'s Transaction Management System holds a PMJAY case, and so which actions may be taken on it next.\\n\\n### Business purpose\\n\\nA PMJAY case is not decided over NHCX. The exchange carries the submission to the scheme and the verdict back, but the decision is taken in the SHA\'s own system, by a named role, on that system\'s schedule. This call is how an integrator reads that queue. It is also the only way to see where a PMJAY case stands, because a status `Task` sent to the scheme over NHCX is refused, first with `PAYR-1018` and then with `PAYR-1008`.\\n\\n### When to use\\n\\nBefore every call to `Adjudicator: act on a case`, because the role that answers is the only one whose action names are legal, and whenever a PMJAY case has gone quiet. The service moves cases on its own schedule, so read the role again rather than assuming the next step.\\n\\n### Preconditions\\n\\n- `caseid` is the scheme\'s case ID, the digits at the end of the case reference the payer issues, not the hospital\'s claim number. The sandbox hands it out inside the `PAYR-1238` refusal of a later request for the same beneficiary, and in the payer\'s acknowledgement and status answers once a request is accepted.\\n- `payerid` is the scheme payer\'s code.\\n- An ordinary ABDM session token on `bearer_auth`, with `Content-Type` and `Accept` set to `application/json`.\\n\\n### Postconditions\\n\\nThe service answers with the role that holds the case in `currentuserrole`, and `errormessage` empty. Once a case is decided, the lookup answers with no role at all. Asked about the hospital\'s own number, it answers `No Data found with the caseid <id>. Please use the current active case id.`\\n\\n### Common mistakes\\n\\n- Sending the hospital\'s claim number as `caseid`.\\n- Acting on the case without reading the role first, and being refused because it has moved.\\n- Reading a pre-authorisation role on a claim as an error. `PPD-Trust` while you are asking about a claim means the case has not yet left the pre-authorisation queue.\\n- Expecting a status API over NHCX for a PMJAY case.\\n\\n### Best practices\\n\\n- Store the scheme\'s case ID beside your own claim number the moment it appears.\\n- Read the role before every action, and again after it.\\n- Expect this lookup and the action call to sit on different hosts. That is how the service is deployed, not a documentation error.\\n\\n### Related scenario\\n\\nA hospital has raised a pre-authorisation that sits at `request.initiated`. It takes the case ID from the payer\'s acknowledgement and posts it here with the payer code. The answer is `PPD-Trust`, so it approves the case as that role with `Adjudicator: act on a case`. After the claim is raised it reads the role again at every step, through `CEX-Trust`, `CPD-Trust`, `ACO-Trust` and `SHA-Trust`, until the lookup answers with no role and the verdict arrives on the claim\'s own callback.\\n\\n### Specification\\n\\nChapter [PMJAY adjudication APIs](/docs/nhcx/v1/roles/provider/pmjay-adjudication-apis) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"caseid","type":"string","required":false,"description":"","encrypted":false},{"name":"payerid","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"caseid":"<case number>","payerid":"<payer code>"},"responses":[{"status":"200","description":"The service answers with the role that holds the case in `currentuserrole`, and `errormessage` empty.","example":{"currentuserrole":"PPD-Trust","errormessage":null}}],"tag":"Other operations","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/nhcxpayerservice/v1/get/user-role \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"caseid\\": \\"<case number>\\",\\n  \\"payerid\\": \\"<payer code>\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/nhcxpayerservice/v1/get/user-role \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"caseid\\": \\"<case number>\\",\\n  \\"payerid\\": \\"<payer code>\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/nhcxpayerservice/v1/get/user-role\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"caseid\\": \\"<case number>\\",\\n        \\"payerid\\": \\"<payer code>\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/nhcxpayerservice/v1/get/user-role\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"caseid\\": \\"<case number>\\",\\n    \\"payerid\\": \\"<payer code>\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let c={title:"Submit the adjudicator: role for a case",sidebar_label:"Submit the adjudicator: role for a case",sidebar_class_name:"api-method api-method--post",description:"Asks the NHCX Payer Service which role in the State Health Agency's Transaction Management System holds a PMJAY case, and so which actions may be taken on...",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-adjudicator.yaml",generated:!0},d,h={},u=[];function p(e){return(0,n.jsx)(o.A,{operation:i})}function l(e={}){let{wrapper:a}={...(0,r.R)(),...e.components};return a?(0,n.jsx)(a,{...e,children:(0,n.jsx)(p,{...e})}):p(e)}}}]);